quests[39037] = { id = 39037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking: Iron Horde Siegebreaker" }
quests[39038] = { id = 39038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking: Resource Rich" }
quests[39040] = { id = 39040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Call to Battle", description = "The favorite star of warlords and generals dominates the sky, offering good fortune to tacticians everywhere. Some say that the battle star hones the instincts of commanders to the point of near-prophecy. If ever you were going to test yourself on the field of battle, now is the time.", completion = "I trust your battles went well?", objectives = "Win 4 Battleground matches.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39041] = { id = 39041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arena Calls", description = "This alignment of the stars is a dire sign, stirring bloodlust and calling warriors to battle to the death in close quarters. Arena masters turn a tidy profit during these days, likely not understanding why their stands are overflowing. Amidst the excitement, great rewards do await those brave, or foolhardy, enough to venture into the arena....", completion = "The wind whispers your name, {name}, and tales of your conquest.", objectives = "Win 10 Arena Skirmish battles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39042] = { id = 39042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Very Best", description = "This alignment of the stars is truly a strange one, causing the tiniest of creatures to gain unnatural aptitude. None of our sages can explain the phenomenon, but cunning tamers have much to gain, especially by testing their skills against those of their peers.", completion = "Well done, {name}. With courage, you have faced every challenge along the way, and battled to claim your rightful place.", objectives = "Defeat 5 players through Find Battle with a team of level 25 pets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39043] = { id = 39043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bitestone Enclave", description = "This is an old drogbar enclave that we used to trade with. Now it is a base of operations for their raids.\n\nI need more time to gather what is left of our warbraves. Go, enter the enclave, and slay any you find in there.\n\nBuy us the time we need to gather our strength.", progress = "Highmountain stands!", completion = "Thank you for clearing us a path. We should have a straight shot at Dargrul now.", objectives = "Slay drogbar in the Bitestone Enclave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39045] = { id = 39045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Zoug" }
quests[39046] = { id = 39046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Harbormaster Korak" }
quests[39047] = { id = 39047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of the Illidari", description = "{name}, Altruis requests that you meet him at Krasus' Landing at once.\n\n<Kor'vas leans in close, her voice an urgent whisper.>\n\nYou must hurry. The Legion has eyes everywhere.", completion = "We need to move quickly. With every moment we sit here, the Legion's hold strengthens.", objectives = "Speak to Altruis the Sufferer at Krasus' Landing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39048] = { id = 39048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Demolitionist" }
quests[39049] = { id = 39049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eye On the Prize", description = "This demon has proved less than useful. I have been using the Scythe of Souls on it, but so far, it has resisted my inquiries. We will see how long that lasts.\n\nI have a different idea...\n\nThere is a fresh inquisitor demon ahead. They are horrific fel casters who see through their floating eyes and specialize in dark pacts. If you steal its power, Jace Darkweaver could use some of it in his ritual to spy on the Legion.\n\nBetter yet, you will gain its power by ripping it from its smoking corpse.", progress = "{name}. I would salute, but I am in the middle of a ritual.", completion = "An inquisitor's essence... perfect. Allari was right.\n\nNow to complete my ritual and spy on the Legion's leadership.", objectives = "Kill Inquisitor Baleful and take his power.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39050] = { id = 39050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meeting With the Queen", description = "We can use some of that essence to complete my ritual. You'll be able to spy upon the Legion leaders and see what they're planning.\n\nUse the nether crucible and complete the ritual.", progress = "If we don't know what they're planning, we're at a disadvantage fighting them.", completion = "That's new. She looks like some kind of spider demon. As if the Legion needed spiders...", objectives = "Complete the ritual to spy upon the Legion leaders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39051] = { id = 39051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "By Any Means", description = "We need to figure out what rock Varedis is hiding under - the only way we're going to do that is by getting inside this prison.\n\nDo what you must.", progress = "A truly impressive display.", completion = "Suramar is not far from here.", objectives = "Gain entrance to the Violet Hold and interrogate Taldath the Destroyer to find out the location of the traitor Varedis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39052] = { id = 39052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blueprints Are Important", description = "The first thing we need to start building ships is a blueprint.  Lucky for you, I snatched some of the best ones from the Iron Docks before we broke out of there.  There is a one problem though...\n\nThese blueprints can get me in big trouble if the Iron Horde finds out.  I need you to memorize them and then destroy the evidence.  Let me know when you are done.", objectives = "Take the blueprints to Crowler at your Garrison. He should be able to decode them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39054] = { id = 39054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shipbuilding", description = "The first thing we need to start building ships is a blueprint. With your help, I grabbed some of the best ones from the Iron Docks before we broke out of there.\n\nLet's make sure these don't fall back into the hands of the Iron Horde. Memorize these blueprints, {class}, and then destroy the evidence. Let me know when you are done.", progress = "You memorize those blueprints yet?", completion = "Hah, we'll make you a sea-dog yet. Let's get started on our first ship!", objectives = "Learn the blueprints and destroy the evidence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39055] = { id = 39055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ship Shape", description = "Now that we have the blueprints, let's get started on our first ship, a transport!  Speak to me when you are ready to begin construction.", progress = "Get that ship started yet?", completion = "We have our first ship!  Great work {name}.  I will get to work preparing her for travel to Tanaan right away.", objectives = "Speak with Yanas to begin construction on a transport ship. Once complete, add it to your collection of ships.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39056] = { id = 39056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naval Commander", description = "We have come a long way in a short time on this shipyard, {name}.  Now it's time to run our first naval mission and control the seas of Draenor!\n\nI will need to setup shop from a high vantage point to plan out these seafaring missions.  Meet me near the shipyard entrance and we can get started.", progress = "Finish a naval mission yet?", completion = "Great work Commander!  You are going to make a great captain one day.", objectives = "Find Merreck Vonder in your Shipyard and complete a Naval Mission.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39057] = { id = 39057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Command of the Seas", description = "Gul'dan wasted no time integrating his Shadow Council minions into every rank of the Iron Horde. The naval fleet that once owed loyalty only to Grommash is now his to command. If we want to fight back, we're going to need more than just a couple of transport ships. We must build an arsenal.\n\nWe need your expertise, commander. Upgrade your dockyards and create a fleet capable of dominating the seas!", completion = "Well done, {name}. These docks are buzzing with activity.\n\n\n\nLet's do some damage.", objectives = "Upgrade to a Level 2 shipyard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39058] = { id = 39058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Critters of Draenor", description = "I love collecting pets, and I've picked up a few unusual pets here in Draenor.  What would you say to a battle?  If you can defeat my humble team, I think we'll both learn a few new tricks.", objectives = "Defeat Erris the Collector in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39059] = { id = 39059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Catch a Banshee", description = "The strange-talking vrykul said I might be able to meet you here. I have orders from Greymane.  It seems he may have a lead on Sylvanas' location.\n\nHe's set up a camp near the base of the mountain. We've run into some troubles, though. It looks like the Horde may have homed in on our position.\n\nWe could use your help. You can take my gryphon. Just speak to me when you're ready to leave.", completion = "It is good you arrived when you did, {name}.", objectives = "Meet with Genn Greymane in Greywatch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39060] = { id = 39060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Combustible Contagion", description = "It is true that we may have a lead on Sylvanas. Though I want nothing more than to get my hands on the Banshee Queen, the situation here at Greywatch requires immediate attention.\n\nYesterday, a regiment of guards returned with word of Forsaken forces in the woods. Several of them bore signs of a blight, similar to the one we endured in Gilneas. It would appear these Forsaken seek to unleash this blight upon Greywatch.\n\nSeek out their caches and destroy them, before the blight overtakes us!", progress = "Have the caches been taken care of?", completion = "The deed is done. \n\nYou have done a great service to the worgen of Greywatch, {name}.", objectives = "Burn the Forsaken Blight Caches near Greywatch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39061] = { id = 39061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whispers from the Dark", description = "We still have little knowledge of the Horde's activities in the region, but I'm hoping you can help change that.\n\nLately the woods have been crawling with Sylvanas' agents. The few we have taken out carried orders from her Dark Rangers, who are no doubt in command of her forces here.\n\nWhile you're on the hunt, keep an eye out for any scouting orders. They may help us pinpoint Sylvanas' objective in the area.", progress = "What have you found?", completion = "Excellent. The puzzle is finally coming together. \n\nWe may not know why Sylvanas' forces are here, but I think we know where they are.", objectives = "Collect the Forsaken Scouting Orders from Dread-Rider Stalkers and Dread-Rider Plaguebringers near Greywatch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39062] = { id = 39062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Skold-Ashil", description = "We have her now! According to these reports, Sylvanas' forces are after something in Skold-Ashil - a vrykul town not far from here. We must make our way there and track her down.\n\nI had previously dispatched Commander Lorna Crowley and a detachment of Gilneas Brigade to scout the position. Meet up with her there and find out what Sylvanas is after.\n\nMeanwhile, I will muster the fleet to assault their outpost. We will have justice if I have to reduce their camp to rubble!", completion = "So the cavalry has arrived? \n\nGood, we must make haste if we wish to uncover Sylvanas' plot before it comes to bear.", objectives = "Meet with Commander Lorna Crowley in Crowley's Overlook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39063] = { id = 39063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shielded Secrets", description = "It's obvious at this point that the Horde wants something in Skold-Ashil. Unfortunately we still don't know what they're after.\n\nWe think the secret lies with the shieldmaidens here, so we need to find out more about them. Some early scouting revealed that they have a method of carving their shields to tell their stories. \n\nGo into the city and find as many of these shields as you can. With luck, we will find what Sylvanas seeks.", completion = "Val'kyr, you say? This is worse that I had imagined. If Sylvanas is able to create more Val'kyr, there will be no limit to her armies!\n\nIt seems the vault is her goal. We must stop her!", objectives = "Examine 6 Engraved Vrykul Shields in Skold-Ashil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39067] = { id = 39067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Upgrading The Fleet", description = "You have been doing a great job out there commander.  However, we are going to need more experience and resources to upgrade this shipyard.  Once we reach our goals, we can upgrade the capacity of the shipyard to hold more ships!", progress = "Finding success on these new naval missions?", completion = "Great work!  We will get to work right away on the upgrade.", objectives = "Collect 1000 garrison resources, 1000 gold and complete 15 naval missions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39068] = { id = 39068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naval Domination", description = "Our naval domination continues!\n\nHowever, we are going to need even more experience and resources to take this shipyard to the next level.  Once we reach our goals, we can upgrade the capacity of the shipyard to hold even more ships!", progress = "Gather those resources yet?  I am ready to get this upgrade started!", completion = "Controlling the seas of Draenor is in our grasp!", objectives = "Collect 2500 garrison resources, 2500 gold and complete 25 naval treasure missions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39069] = { id = 39069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Treasure 024 - Moonclaw Vale - twh" }
