quests[39107] = { id = 39107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Even Bigga Score", description = "So these mooks in Tanaan, they be carryin' all manner of valuable treasures. It still be complicated, but I can give ya a lot more now!", progress = "So you've got every last one?", completion = "Eh, ya got dem all! Dat's wonderful for the both of us. I can give ya dis much...", objectives = "Obtain Dingy Iron Coins for Griftah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
