quests[39114] = { id = 39114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Ruins - Medium Treasure 000 - twh" }
quests[39117] = { id = 39117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shriek No More", description = "Papa loved this village. He'd never hear of leaving, even in these dread times.\n\nBefore he died, he told me what attacked him: a monstrous falcon we call Rotbeak.\n\nYou're fighting these undead, aren't you? Will you avenge my father? If so, you can find the beast northwest of here, patrolling our western route to the sea.", progress = "Papa always said the only way he'd leave here would be feet-first.\n\nI wish he'd been wrong.", completion = "Thank you. Grisly, eh? I think I'll mount it over the door.\n\nI want you to have this, too. Fresh-caught mossgill was Papa's favorite.", objectives = "Find Rotbeak along the Bradensbrook, and collect the beast's head.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39118] = { id = 39118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lower Citadel Speed Tracking" }
quests[39119] = { id = 39119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Skold-Ashil", description = "<insert>" }
quests[39120] = { id = 39120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Shield Forger" }
quests[39121] = { id = 39121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Haunted Manor" }
quests[39122] = { id = 39122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ending the New Beginning", description = "The Banshee Queen is here! I'd recognize those tainted arrows anywhere.\n\nThis is the moment we have been fighting for. Sylvanas will answer for her crimes against Varian Wrynn and the Alliance!\n\nTo arms!", completion = "You're awake! We nearly lost you there... \n\nIt's a good thing we managed to get you and Greymane out of there in time, otherwise we wouldn't have been able to reverse Sylvanas's poison. It's a shame she got away, but her plans in Skold-Ashil failed and we have you to thank for it. \n\nI'm sure Greymane will order a commendation for you once he is fully recovered. You did a great thing here, {name}. \n\nGilneas is in your debt.", objectives = "Confront Sylvanas in the Vault of Eyir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39123] = { id = 39123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lion Stalkin'", description = "The hills are crawlin' with lions that stalk their prey from afar. These big cats will pounce at anything that catches their eye, including |5{race}. \n\nWhile most would fall to such a formidable predator, anyone in my huntin' party would be able to best those beasts.\n\nProve you've got what it takes by taking down a few of those stalkers.", completion = "Not a scratch on ya that I can see. I bet those lions never saw ya comin'!", objectives = "Hunt Pinerock Stalkers and Prowlers in Pinerock Basin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39124] = { id = 39124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moose Shootin'", description = "Highmountain is home to wildlife that can't be hunted anywhere else in the world. Tell me, {name}, have you ever laid eyes on a moose before? \n\nThe roaming Elderhorn may look like gentle giants, but only a fool would underestimate their strength. \n\nThey should prove to be a good challenge, even for someone as experienced as you.", progress = "Ya can't be huntin' Elderhorn if you're lingerin' around camp.", completion = "You've hunted the Highmountain Elderhorn and lived to tell about it. That's not a feat that most can say they've accomplished. Color me impressed.", objectives = "Hunt Pinerock Elderhorn in Pinerock Basin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39125] = { id = 39125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demon Destroyer", description = "The demons spreading this corruption must be dealt with. Kill their generals and their plans will unravel.\n\nI have a gift for you. This horn was given to me by Odyn himself, use it to strike down all that stand in your way.\n\nThe gods will surely smile upon you if you thwart the advances of Legion.", objectives = "Slay Doomcaller, Sneermaw, and Grinchain", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39126] = { id = 39126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing the Fountain", description = "The blood from an impaled dreadlord is flowing into a fountain at the base of Valhallas. Following orders given by their \"God-King\" the vrykul are drinking from the fountain. \n\nThe demon blood is driving the vrykul mad and it's giving them greater power than they deserve.\n\nTake this acorn. Throw it into the fountain. My ravens will take care of the rest.", objectives = "Cleanse the demon blood from the fountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39127] = { id = 39127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beyond the Wall", description = "We received word the Shado-Pan have begun a counter attack in to Townlong Steppes. It sounds like they are going after the root of the yaungol invasion.\n\nThe pandaren have not traveled in force in to Townlong for thousands of years. The Shado-Pan are strong and brave, but they are also proud and few. They will need help from heroes like yourself. Can you travel through the Gate of Winter's Blossom in the northwest? Find the Shado-Pan leaders and lend your help and experience?", completion = "Welcome to Townlong Steppes. If you insist on wandering in to the darkest places of Pandaria then far be it from me to not put you to good use.", objectives = "Speak with Taran Zhu at the Longying Outpost in Townlong Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39128] = { id = 39128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanaan Vignette" }
quests[39129] = { id = 39129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ill Tempered", description = "<Prying the lid off the scroll case reveals a plan by the Iron Horde to use large fish in the oceans around Draenor to interfere with Alliance and Horde naval power. Incredibly, the plan seems to have already worked on smaller sharks, but only up to a point.>", objectives = "Take the Shark Brainwashing Plans to your garrison shipwright.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39130] = { id = 39130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - River: Vignette: Purging the River - TRACKING - twh" }
quests[39131] = { id = 39131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Possessions of Power", description = "Echoes of a thousand worlds swirl in the palm of your hand. Its true value lies in the eye of the beholder.", objectives = "Seek those who may offer insight into the origins of the shard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39132] = { id = 39132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The New Chieftain", description = "So you are the one of whom Ebonhorn foretold. I thought you would be taller.\n\nOur High Chieftain Ulan has been slain by the drogbar when they seized the hammer.\n\nHis daughter, Mayla Highmountain, has now taken on the burden of High Chieftain.\n\nYou can find her on the northern bluff with what few forces we have left to defend this place.\n\nShe will have need of you.", sourceObjective = "Find Mayla Highmountain.", sourceObjectiveStatus = "unverified-source-field" }
quests[39133] = { id = 39133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Time to Talk", description = "Dargrul has sent his pets to do battle with us.\n\nWe need to crush these elementals before their rage swarms into Thunder Totem.", progress = "We will all be honorary masons if this keeps up much longer.", completion = "It has been a long time since the earth itself has moved against us like this.", objectives = "Destroy 8 Enraged Ambershard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39134] = { id = 39134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrathshard", description = "The Underking has used the Hammer of Khaz'goroth to render the mountainside into a weapon against us. The hammer is a tool for creation, not a weapon for his amusement!\n\nEven now, his crystal servant, Wrathshard, is driving these elementals out of the mountain down upon my people.\n\nWe must hold the bridge against this onslaught.\n\nEnter the cave, find Wrathshard, and send him back to his master in pieces.", progress = "Dargrul always was a vile creature. I never realized to what extent until he got his hands on that hammer.", completion = "I suspect this is not the last of Dargrul's assaults. He is still learning the powers of the Hammer like a child with a new toy.", objectives = "Slay Wrathshard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39135] = { id = 39135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sundered Tribe", description = "Dargrul didn't just take the Hammer of Khaz'goroth. He slew the High Chieftain -- my father -- to get it.\n\nThere are some who claim our tribe died with my father, and they have gone their separate ways.\n\nBut you... you look like someone they might listen to. You might convince them to return or at least send reinforcements.\n\nCan you speak with the representatives of the three tribes?", objectives = "Speak with the Rivermane, Bloodtotem, and Skyhorn chieftains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39138] = { id = 39138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "March Forth and Conquer", description = "You should make sure that we do not lose momentum, Highlord. There is still much to be done in Azsuna.\n\nWe have a map of the island set up near the front of the sanctum. Meet me there and you can delegate your forces to handle important tasks in the area.", objectives = "Use the Command Map to send your followers on three missions to Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39142] = { id = 39142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Testing a Theory", description = "Now that the Bloodstone has fed, I hope to use its power to bend the will of demons that would otherwise not be so easily controlled.\n\nOf course, this is all theory. I have never witnessed the direct effect of the Bloodstone's power on a demon. This is where you come in.\n\nI have procured a few imps that should make suitable test subjects. Use the Bloodstone on them and report back to me with your findings.", progress = "Have you tested the Bloodstone yet? I have imprisoned a few imps in the cave behind me that should make suitable test subjects.", completion = "The subject died during the testing process? Well that was unexpected.\n\nNonetheless, you've held up your end of the bargain. I suppose it's time for me to fulfill mine.", objectives = "Use the Bloodstone on an Imprisoned Imp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39149] = { id = 39149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Village in Peril", description = "Another outsider? Some bloke named Jarod just went off to our village down the road claiming he might be able to help us with our problem.\n\nIf you're here to help as well, then you best speak to the Mayor.\n\nJust know this is a bad time, and he's got an itchy trigger finger.", completion = "We don't need any help, and we don't like strangers wanderin' around on our land.", objectives = "Speak to Mayor Heathrow at Bradensbrook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39151] = { id = 39151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forging the Artifact", description = "We've certainly got our work cut out for us, but not to worry. There's nae weapon in existence that ye can't improve, legendary ones included!\n\nThis anvil's only powerful enough to imbue your artifact once before we'll need something better, but that'll have to do fer now.", objectives = "Use Valgar's anvil to imbue your artifact with a new power.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39152] = { id = 39152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felwrought Annihilator Looted" }
quests[39153] = { id = 39153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreadwake's Dilemma", description = "The situation has taken a dire turn, {name}. We were unprepared for Greymane's sudden assault, with only a token force left behind at Dreadwake's Landing, and we are paying the toll.\n\nThe beach is now swarming with worgen infiltrators, and if the cannons breach our defenses, they will likely swarm in on us. We're spread too thin here to take the fight to them, but you could change that.\n\nWipe them out.", completion = "It looks like the ravens will feast on worgen flesh today, {class}.\n\nWell done.", objectives = "Kill 10 Greywatch Saboteurs or Infiltrators in Greymane's Offensive.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39154] = { id = 39154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Skold-Ashil", description = "Thanks to your initiative, {class}, the situation at Dreadwake's Landing is under control. We have no time to rest on our laurels, however - Sylvanas's mission must still be carried out.\n\nThe dark rangers are heading up operations in Skold-Ashil from the tower overlooking the river junction. Seek them out there, and see if you can aid in completing this task.", completion = "You seem surprised to find me here? I was surprised as well, to find that my forces were unable to even breach the city of these cursed vrykul! \n\nThe time has come to employ some different tactics, and your arrival couldn't have been more fortuitous.", objectives = "Meet with the dark rangers in Ranger's Foothold, outside of Skold-Ashil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39155] = { id = 39155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Becoming the Ascendant", description = "It would seem that the engravings depict a rite of ascension, which allows the shieldmaidens to enter the vault. I believe we can use this to our advantage.\n\nYou must become the next ascendant.\n\nGo to the temple and perform the rites. Should you need to wade through the corpses of the shieldmaidens to do so, then so be it. \n\nFind me when you have completed this task, and we will take the vault for the Horde!", completion = "The hero returns, and with the barrier disabled. I will see that you are commended for this. \n\nBut first, we must claim this vault!", objectives = "Seek the blessings at the four shrines in the temple at Skold-Ashil, then commune with the statue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39156] = { id = 39156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uther's Spirit Honored" }
