quests[39173] = { id = 39173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel Legendary Pet Tracking Quest 15" }
quests[39174] = { id = 39174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guiding Light Tutorialized" }
quests[39175] = { id = 39175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gems of the Apexis", description = "Listen, boss. I know you're a jewelcrafter. It's OK, I totally understand - I like money, too!\n\nI heard some of them bird fellas talking about some new gem-cuttin' device they got up in Tanaan. I'd be interested in checkin' it out myself, but I've got this whole shipyard mess to deal with right now.", completion = "Yes?", objectives = "Find Sun-Sage Chakkis in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39176] = { id = 39176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mastery Of Taladite", description = "You - you are a gemcutter, no? You have the look of it in the twitch of your knuckles, in the focus of your eyes.\n\nI've been looking for something specific out here in Tanaan. We did not find it in our excavations in Arak... but the Apexis did not only dwell in Arak.\n\nWhat I am looking for is a storied Apexis construct that specialized in cutting gems. Be on the lookout, jewelcrafter. Such a marvel could benefit the both of us.", completion = "<The construct lies amidst rubble, in disrepair.>\n\n<Judging by the tools on its manipulator arms, this construct does appear to be designed for gemwork.>", objectives = "Find the Apexis Gemcutting Construct.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39177] = { id = 39177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruined Construct", description = "<It is in disrepair, but it is not broken. More than anything, the construct appears to be in need of re-energizing.>\n\n<A slot on the backside of the machine lies open, waiting to accept... whatever the Apexis used as a source of energy.>", completion = "Are you responsible for the return of this construct, {name}? It came barrelling through our camp like it was on a mission. It took three of the warders to tackle and subdue it, but for the time being, it appears content to stay here.", objectives = "Repair the Apexis Gemcutter Construct by inserting 1000 Apexis Crystals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39178] = { id = 39178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moose on the Loose", description = "There's been chatter around the hunters' lodge about a crazed moose that is terrorizing the basin. \n\nI've never laid eyes on the beast myself, but they say its antlers are illuminated with magic. \n\nWhere other lesser hunters have tried and failed, you will prevail, and collect me a one-of-a-kind trophy!", progress = "I'm looking forward to hanging the antlers of an ancient spirit within the walls of the hunters' lodge!", completion = "These antlers are going to look quite impressive hanging from the walls of the hunters' lodge.", objectives = "Collect the antlers of the cursed ancient spirit, Morashu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39179] = { id = 39179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodstone Bandit", description = "Something of personal value has been taken from me, and my work here cannot continue until I get it back.\n\nTo most it would appear to be an ordinary stone, but it is so much more than a simple rock - it lives and breathes!\n\nThe nearby naga have been snatching anything with any sort of magical significance, my stone included. Fortunately, they do not know how to access its power.\n\nReturn my stone to me, and I will consider your request for help.", progress = "Have you recovered my Bloodstone yet?", completion = "You're quite resourceful. I can see why Ritssyn likes to send you on errands.", objectives = "Recover Kira's Bloodstone from Narashi Spitescale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39180] = { id = 39180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Zangarmarsh!", description = "The Cenarion Circle's main expeditionary force in Outland is known as the Cenarion Expedition.  Though it began as a small venture controlled directly by the Cenarion Circle, it's become a large and fairly autonomous body.\n\nThe expedition's leader, Ysiel Windsinger, has asked us to direct volunteers to her outpost.  Report to her at the Cenarion Refuge in eastern Zangarmarsh.  Take the main path to the west and it will lead you directly there.", completion = "Welcome to Cenarion Refuge, {name}.  I hope you've come to aid us in our mission.  We've much work ahead of us.", objectives = "Speak to Ysiel Windsinger at the Cenarion Refuge in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39181] = { id = 39181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Zangarmarsh!", description = "The Cenarion Circle's main expeditionary force in Outland is known as the Cenarion Expedition.  Though it began as a small venture controlled directly by the Cenarion Circle, it's become a large and fairly autonomous body.\n\nThe expedition's leader, Ysiel Windsinger, has asked us to direct volunteers to her outpost.  Report to her at the Cenarion Refuge in eastern Zangarmarsh.  Take the main path to the west and it will lead you directly there.", completion = "Welcome to Cenarion Refuge, {name}.  I hope you've come to aid us in our mission.  We've much work ahead of us.", objectives = "Speak to Ysiel Windsinger at the Cenarion Refuge in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39182] = { id = 39182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Terokkar Forest!", description = "We have lost contact with the druids of the Cenarion Thicket\n\nThe Warchief has commanded any able bodies of the Horde to venture into Terokkar Forest and discover what has happened.\n\nThe thicket can be found by heading northwest through Terokkar Forest from Zangarmarsh.", completion = "I'm glad that Stonebreaker Hold sent you.  The druids of the thicket have been slain!  Only myself and one other have survived, and he's insane.\n\nI don't know what happened, but I intend to get to the bottom of it.  Whatever it was, it happened quickly and feels unnatural.\n\nWill you help me?", objectives = "Speak with one of the druids at the Cenarion Thicket in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39183] = { id = 39183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Immaculate Critical Strike Taladite" }
quests[39184] = { id = 39184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Immaculate Haste Taladite" }
quests[39185] = { id = 39185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Immaculate Mastery Taladite" }
quests[39186] = { id = 39186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Immaculate Multistrike Taladite" }
quests[39187] = { id = 39187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Immaculate Stamina Taladite" }
quests[39188] = { id = 39188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Terokkar Forest!", description = "We have lost contact with the druids of the Cenarion Thicket\n\nThe King has commanded any able bodies of the Alliance to venture into Terokkar Forest and discover what has happened.\n\nThe thicket can be found by heading northwest through Terokkar Forest from Zangarmarsh.", completion = "I'm glad that Stonebreaker Hold sent you.  The druids of the thicket have been slain!  Only myself and one other have survived, and he's insane.\n\nI don't know what happened, but I intend to get to the bottom of it.  Whatever it was, it happened quickly and feels unnatural.\n\nWill you help me?", objectives = "Speak with one of the druids at the Cenarion Thicket in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39189] = { id = 39189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Nagrand!", description = "We have lost contact with the druids of the Cenarion Thicket\n\nThe Warchief has commanded any able bodies of the Horde to venture into Terokkar Forest and discover what has happened.\n\nThe thicket can be found by heading northwest through Terokkar Forest from Zangarmarsh.", sourceObjective = "Speak with one of the druids at the Cenarion Thicket in Terokkar Forest.", sourceObjectiveStatus = "unverified-source-field" }
quests[39191] = { id = 39191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legacy of the Icebreaker", description = "The greatest warrior should wield the greatest weapons. Long ago a great king, Magnar Icebreaker, wielded weapons crafted from a scale of the mightiest dragon in the land. He should be here, but he is not. Instead he languishes in his tomb.\n\nHis son, Hruthnir, is here. He will lead you to the tomb. If Magnar can be saved, do so. Either way, return with his weapons.", progress = "You have done well. You will bring many victories to these Halls.", completion = "A great deed was done today. I have gained a mighty {class}, and you a powerful artifact.", objectives = "Deal with Magnar Icebreaker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39192] = { id = 39192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forge of Odyn", description = "This Forge has been working for longer than your race has existed; we might know a few things. Your weapon is powerful, it will take my personal forge in order to work it.\n\nWe can work the artifact to provide various improvements, provided you have enough experience with it. Let's give it a try shall we?", completion = "Your weapon has untold potential! You will need to get more acquainted with it first and we can work on it some more.", objectives = "Use the Forge of Odyn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39193] = { id = 39193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellfire Assault", description = "If you are to breach the walls of the citadel, you must first face siege equipment and forces led by Siegemaster Mar'tak.\n\nI wish you luck in gaining entry to Hellfire Citadel with your limbs intact.", objectives = "Defeat the Hellfire Assault in Hellfire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39195] = { id = 39195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gems of the Apexis", description = "Commander! I've noticed you have been keeping up with your jewelcrafting, despite all of this war going on. I find that to be most admirable.\n\nI overheard some of the arakkoa discussing a gemcutting device that they believe is located within Tanaan Jungle. They got their information from one named \"Chakkis.\"\n\nJust thought you might be interested.", completion = "Yes?", objectives = "Find Sun-Sage Chakkis in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39196] = { id = 39196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Nagrand!", description = "The Warchief has asked for any able bodied champions of the Horde to ride to the aid of Garadar.\n\nThe home of the Mag'har, lies to the south, in Nagrand. Take the southern road out of the marsh, then turn east at the first fork and look for a large settlement on the lake.\n\nReport to Captain Kroghan there and offer him what assistance you can. Garadar must not fall!", completion = "<Even though he endeavors to hide it, a look of relief spreads over Kroghan's face.>\n\nIt's about time you got here! Granted, you're not an army, but any able-bodied {race} than can wield a weapon or chant a spell is welcome here. The people of Garadar are kin to all the Horde and we are proud to shed our blood in their defense.", objectives = "Speak with Captain Kroghan at Garadar in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39197] = { id = 39197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Nagrand!", description = "The King has requested you represent him with the Kurenai settlement of Telaar in Nagrand.\n\nSeek out Warden Moi'bff Jill upon arrival.", completion = "You are welcome here in Telaar.", objectives = "Speak with Warden Moi'bff Jill at Telaar in Nagrand on Outland.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39198] = { id = 39198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Blade's Edge Mountains!", description = "The Warchief is calling for champions to put an end to the ogre threat in Blade's Edge Mountains. Make your way north into the mountains, to the orcish stronghold of Thunderlord Stronghold and let Gor'drek know of our plight. Any help he can spare would be most welcome.", completion = "Thank you for coming, {class}. We have many enemies here and we can use all the help we can get.", objectives = "Travel to Thunderlord Stronghold in the Blade's Edge Mountains and speak with Gor'drek.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39199] = { id = 39199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Blade's Edge Mountains!", description = "The Alliance forces of Sylvanaar in the Blade's Edge Mountains require reinforcements.\n\nThe King has asked for any able bodied members of the Alliance to journey to the mountains along the northern border of Zangarmarsh.", completion = "Thank you for coming. We could use more able bodies.", objectives = "Speak with Rina Moonspring at Sylvanaar in the Blade's Edge Mountains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39200] = { id = 39200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lynore's Fury", description = "It appears Eira has a present for you, your first valarjar! You lead 'em, I'll make sure their weapons and armor are ready for war!You will learn:", sourceObjective = "Speak with Lynore.", sourceObjectiveStatus = "unverified-source-field" }
quests[39201] = { id = 39201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Netherstorm!", description = "The goblins of Area 52 in Netherstorm have called for assistance from any able bodied champions willing to provide them the support they need in their endevours.\n\nThe Warchief feels their position and aid in the region will provide a tactical advantage against the nearby forces of Kael'thas.\n\nArea 52 can be reached by following the northeastern road of Blade's Edge Mountains until you see the world crumbling away into the Twisting Nether.", completion = "Hey there. Looking for work? Perfect!", objectives = "Report to Rocket-Chief Fuselage at Area 52.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39202] = { id = 39202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Netherstorm!", description = "The goblins of Area 52 in Netherstorm have called for assistance from any able bodied champions willing to provide them the support they need in their endevours.\n\nThe King feels their position and aid in the region will provide a tactical advantage against the nearby forces of Kael'thas.\n\nArea 52 can be reached by following the northeastern road of Blade's Edge Mountains until you see the world crumbling away into the Twisting Nether.", completion = "Hey there. Looking for work? Perfect!", objectives = "Report to Rocket-Chief Fuselage at Area 52.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39203] = { id = 39203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Dragonblight!", description = "The Warchief wishes to reinforce the Horde's presence at Agmar's Hammer in the Dragonblight.\n\nThe fortress is a vital staging point for our assault on Icecrown and pivotal to containing the chaotic magic energies being released throughout the land.\n\nReport to Archmage Aethas Sunreaver.", completion = "What took you so long? Time waits only for Aspects, {race}.\n\nWe have much work to do, you and I.", objectives = "Speak with the Image of Archmage Aethas Sunreaver at Agmar's Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39204] = { id = 39204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Dragonblight!", description = "Volunteers are needed to aid the Silver Covenant forces in the Dragonblight as they attempt to counter the chaotic arcane energies that threaten to rip the land apart.\n\nThose skilled in fighting dragons and undead are greatly welcome.\n\nThose willing to answer the call should report to Archmage Modera at Stars' Rest in Dragonblight.", completion = "I've been expecting you, {class}. We have much work to do, you and I.", objectives = "Speak with the Image of Archmage Modera at Stars' Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39205] = { id = 39205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twisted Garden" }
quests[39206] = { id = 39206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Grizzly Hills!", description = "We've received a request for help from our base in the Grizzly Hills. Go to see Conqueror Krenna.\n\nShe's attempting to secure all of the natural resources. Just watch your back around her. The word is that she's aggressive even for an orc.\n\nYou can reach her by traveling east from Dragonblight.", completion = "Who are you?\n\nTell me why I shouldn't split you in two where you stand!", objectives = "Present yourself to Conqueror Krenna at Conquest Hold in the Grizzly Hills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39207] = { id = 39207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Grizzly Hills!", description = "While we focus to hold our ground at Wintergarde and deal with the unfolding events of the Wrathgate, battalions from as far away as Westfall battle their way through the dense foliage and inhospitable denizens of Grizzly Hills. All in hopes of finding an alternate route into Icecrown.\n\nLieutenant Dumont, stationed at Amberpine Lodge, has enlisted the aid of able bodied citizens willing to risk life and limb in the uncharted wilds. Will you rise to meet this challenge?", completion = "Savage monsters - those Horde.\n\nPayback will come for what they've done. You can count on at least that much, {class}.\n\nNow, it's time to put you to work.", objectives = "Report to Lieutenant Dumont at Amberpine Lodge in western Grizzly Hills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39208] = { id = 39208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zul'Drak", description = "Our death knight allies in Zul'Drak are in need of heroes to aid them in securing the troll lands from the Scourge.\n\nThose willing to aid should travel to the southwestern camp of Ebon Watch and speak with Stefan Vadu there.", progress = "What have you got there, {race}?", completion = "<Stefan reads the missive, then crumples it up and tosses it into the fire.>\n\nOld news. The Argent Crusade is - once again - late to the party. We've been tracking Drakuru since Grizzly Hills. He is slated for eradication.", objectives = "Report to Stefan Vadu at Ebon Watch in Zul'Drak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39209] = { id = 39209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sholazar Basin", description = "Hemet Nesingwary was last heard from leading an expedition into the jungle depths of Sholazar Basin. His expedition has not been heard from since.\n\nMonte Muzzleshot is a pilot who was dispatched to provide them supplies, but he hasn't returned, either.\n\nVolunteers are needed to mount an expedition to find the missing expedition. Monte's flying machine was last seen in the Wildgrowth Mangal south of the Suntouched Pillar in Sholazar Basin.", completion = "Aye, Hemet's here. He's at the camp, just go northwest toward the river and you'll soon see it. And for the love of the Light, lad, have him send someone to cut me down!", objectives = "Speak with Monte Muzzleshot in the Wildgrowth Mangal of Sholazar Basin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39210] = { id = 39210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Magical Kingdom of Dalaran", description = "The Kirin Tor have moved their city here to Northrend.\n\nNo longer does Dalaran sit under its protective dome on the shores of Lordamere Lake. Now the city magically floats above the Crystalsong Forest.\n\nThey believe you to be ready for your journey to the city. Look for the teleportation crystal in Crystal Song Forest.\n\nWhen you arrive, seek out Archmage Celindra.", completion = "Welcome to Dalaran.", objectives = "Report to Archmage Celindra at The Violet Gate in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39212] = { id = 39212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sholazar Basin", description = "Hemet Nesingwary was last heard from leading an expedition into the jungle depths of Sholazar Basin. His expedition has not been heard from since.\n\nMonte Muzzleshot is a pilot who was dispatched to provide them supplies, but he hasn't returned, either.\n\nArchmage Pentarus in Dalaran is standing by with a flying machine to take you to the last known location of Monte Muzzleshot.", completion = "Aye, Hemet's here. He's at the camp, just go northwest toward the river and you'll soon see it. And for the love of the Light, lad, have him send someone to cut me down!", objectives = "Talk to Archmage Pentarus when you're ready to leave for Sholazar Basin. When you arrive, speak with Monte Muzzleshot in the Wildgrowth Mangal of Sholazar Basin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39214] = { id = 39214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eye of Odyn", description = "It is time to begin the war in Azeroth. We have prepared a tool for you to direct your warriors and your own operations from here. It is called the Eye of Odyn. \n\nIf you will follow me, I will take you to it, and someone that will help you use it.", completion = "It has been a while since I've talked to the living. I hope you don't mind if I assist you. Being slain in combat has given me a calmer outlook in this emergency than other warriors.", objectives = "Go to the Eye of Odyn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39216] = { id = 39216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ready to forge Tracking Bit" }
quests[39217] = { id = 39217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Hate, Excavate!", description = "Well {name}, the good news is that our excavation team breached a chamber below right outside some sort of vault. The bad news is that the Horde were there too. Go down there and take a look.", completion = "Good work {name}! It's not a pretty situation down there.", objectives = "Harrison Jones in Ashran wants you to investigate the deepest part of the Ashran Excavation, The Breach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39219] = { id = 39219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Iron Bulwark", description = "The Siegemaster within Hellfire Citadel has been working on a special machine she calls the Iron Reaver.\n\nWith any luck, she has not yet completed its construction, but you know what happens when we rely on luck...", objectives = "Defeat the Iron Reaver in Hellfire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39221] = { id = 39221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pits of Mannoroth", description = "In the Hellfire Citadel, they work to corrupt a magnaron with fel energy within the Pits of Mannoroth.\n\nIf you delve into the fel pools of that place, be on your guard.", completion = "I wonder if dat magnaron fel into da pool. Get it, mon?", objectives = "Defeat Kormrok in Hellfire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39222] = { id = 39222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Court of Blood", description = "A council of orc clans has assembled and must be adjourned... permanently.\n\nGurtogg Bloodboil of the Bleeding Hollow, Jubei'thos of the Burning Blade, and Dia Darkwhisper of the Shadowmoon clan can all be found within the accursed walls of Hellfire Citadel.", objectives = "Defeat the Hellfire High Council in Hellfire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39223] = { id = 39223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deadeye's Vision", description = "Kilrogg Deadeye has led his clan down a dark path that he cannot return from.\n\nDemon blood coursing through his veins, he awaits the moment of his death--or yours--in Hellfire Citadel.", objectives = "Defeat Kilrogg Deadeye in Hellfire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39225] = { id = 39225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maw of Souls", description = "Falling into the heart of the mausoleum in Auchindoun, Teron'gor gorged upon hundreds of draenei souls, becoming a bloated abomination in the process. \n\nNo longer recognizable as an orc, Teron'gor gave up his old name and has taken on the mantle of Gorefiend.", completion = "I wouldn't know dat monster started off as an orc if Saurfang hadn't told me.", objectives = "Defeat Gorefiend in Hellfire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39226] = { id = 39226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iskar's Clutch", description = "I'm afraid I have bad news about someone we once trusted. The arakkoa known as Iskar has gone too far in his desire to regain flight, and has joined with Gul'dan to regain his highborn body.\n\nWith it came the price of fel corruption and being doomed to fall at your hands.", objectives = "Defeat Shadow-Lord Iskar in Hellfire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39227] = { id = 39227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amphitheater of the Eternal", description = "The Exarch betrayer, Socrethar, was defeated with the assistance of Lady Liadrin and Exarch Maladaar.\n\nBut, he has returned. His vile spirit  is now within the Soulbound Construct in Hellfire Citadel, and must be destroyed once again.", objectives = "Defeat the Soulbound Construct  in Hellfire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39228] = { id = 39228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temple of Tyranny", description = "Tyrant Velhari was once a promising vindicator, but has turned to Shadow for reasons known only to her.\n\nPurge this Eredar of darkness.", completion = "Anotha follower of da darkness falls before ya.", objectives = "Defeat Tyrant Velhari in Hellfire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39229] = { id = 39229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grommash's Torment", description = "We believe Grommash has not yet accepted Gul'dan's offer, and may even have avoided drinking the blood offered to him.\n\nBut Gul'dan has set Fel Lord Zakuun on Grommash. This demon is Gul'dan's best-known torturer.\n\nI fear for Grommash. If he is turned, I fear for us all.", objectives = "Defeat Fel Lord Zakuun in Hellfire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39230] = { id = 39230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Felborne Breach", description = "Summoned by Gul'dan from the depths of the Twisting Nether, Xhul'horac is one of most powerful of the Void Revenants--a race of parasitic void-beings that tear holes through the planes of reality, consuming and absorbing the energies and beings within.\n\nGul'dan has twisted Xhul'horac, feeding him overwhelming fel energy, and using his powers to tear open the portals through which he plans to rally the forces of the Burning Legion.", objectives = "Defeat Xhul'horac in Hellfire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39231] = { id = 39231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destructor's Rise", description = "We believed we were done with Mannoroth, at least for a time. But Gul'dan is more powerful than we had predicted.\n\nMannoroth is nearly back in this world. His bones have been seen within the citadel, and he must be destroyed before he can reach his full power.", completion = "Dat bag of bones be gone again.", objectives = "Defeat Mannoroth in Hellfire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39232] = { id = 39232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Gate", description = "We have heard rumors that one of the strongest of the eredar could soon enter this world through the Black Gate.\n\nIf these rumors are to be believed, it could even be Archimonde the Defiler. Should he arrive uncontested, Draenor itself is likely to fall.", completion = "Ya saved Draenor from one of da strongest demons in all creation, Commander. Dey will sing songs of your victory.", objectives = "Defeat Archimonde in Hellfire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39233] = { id = 39233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Hate, Excavate!", description = "At last {name}, you've arrived and not a moment too soon. Quick, go down into the mine and take a look at what we've discovered. You may run into some Alliance down there. It is a minor inconvenience that is easily remedied.", completion = "Good work {name}! You see the mess the Alliance has made I'm sure.", objectives = "Belloc Brightblade in Ashran wants you to investigate the deepest part of the Ashran Excavation, The Breach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39234] = { id = 39234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Peak Urgency", description = "BYou've been summoned by Master Mathias Shaw of SI:7. He's waiting for you in the depths beneath Dalaran. Be wary - there have been reports of disappearances in those sewers.", sourceObjective = "Speak to Mathias Shaw in the sewers beneath Dalaran.", sourceObjectiveStatus = "unverified-source-field" }
quests[39235] = { id = 39235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buba" }
quests[39236] = { id = 39236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let's Get To Work", description = "Now that the shipyard is complete, we need to get busy making ships!  Solog ran off to the dry docks, why don't you meet him down there?  He said he had a plan.", completion = "I love the smell of fresh-cut wood and tar! Are you ready to start construction?", objectives = "Meet Solog at the dry docks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39241] = { id = 39241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shipbuilding", description = "The first thing we need to start building ships is a blueprint. With your help, I grabbed some of the best ones from the Iron Docks before we broke out of there.\n\nLet's make sure these don't fall back into the hands of the Iron Horde. Memorize these blueprints, {class}, and then destroy the evidence. Let me know when you are done.", progress = "You memorize those blueprints yet?", completion = "Hah, we'll make you a sea-dog yet. Let's get started on our first ship!", objectives = "Learn the blueprints and destroy the evidence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39242] = { id = 39242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ship Shape", description = "You want to take the fight to Gul'dan? You need a transport! Speak to me when you are ready to begin construction.", progress = "Get that ship started yet?", completion = "It is done. Quite the beauty! You provide the army, she'll get 'em where they need to go.\n\nI will prepare her for the trip to Tanaan.", objectives = "Speak with Solog to begin construction on a transport ship. Once complete, add it to your collection of ships.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39243] = { id = 39243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naval Commander", description = "You're a natural at this, {name}. You've got the salt in your veins. Now it's time to run our first naval mission and control the seas of Draenor!\n\nYou will want a high vantage point to plan out these seafaring missions.  I know a good spot just up the path behind us. Meet me near the shipyard entrance and we can get started on our first mission.", progress = "Finish a naval mission yet?", completion = "Great work Commander!  You are going to make a great captain one day.", objectives = "Find Rolash Wavechaser at your shipyard and complete a Naval Mission.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39245] = { id = 39245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Upgrading The Fleet", description = "You have been doing a great job out there commander.  However, we are going to need more experience and resources to upgrade this shipyard.  Once we reach our goals, we can upgrade the capacity of the shipyard to hold more ships!", progress = "Finding success on these new naval missions?", completion = "Great work!  We will get to work right away on the upgrade.", objectives = "Collect 1000 garrison resources, 1000 gold and combat 15 naval missions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39246] = { id = 39246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naval Domination", description = "Our naval domination continues!\n\nHowever, we are going to need even more experience and resources to take this shipyard to the next level.  Once we reach our goals, we can upgrade the capacity of the shipyard to hold even more ships!", progress = "Gather those resources yet?  I am ready to get this upgrade started!", completion = "Controlling the seas of Draenor is in our grasp!", objectives = "Collect 2500 garrison resources, 2500 gold and complete 25 naval treasure missions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39247] = { id = 39247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunt", description = "This hunt is yours to lead, {name} - a select few Illidari will join you to make sure Varedis meets his end.\n\nThe rest of us must stay behind; a small team will have the best chance of making it to his hold undetected.\n\nWe will meet you at Krasus' Landing to see you off when you are ready.", completion = "What of the others? Did they...?\n\nI see. They gave their lives for a worthy cause - the Twinblades will change the tide of this war, mark my words.", objectives = "Obtain the Twinblades of the Deceiver from Varedis Felsoul in Suramar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39248] = { id = 39248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellfire Assault", description = "If ye want to breach the walls o' the citadel, ye must first face siege equipment and forces led by Siegemaster Mar'tak.\n\nGood luck gainin' entry to Hellfire Citadel with yer limbs intact.", objectives = "Defeat the Hellfire Assault in Hellfire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39249] = { id = 39249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Iron Bulwark", description = "The Siegemaster in Hellfire Citadel has been working on a special machine she calls the Iron Reaver.\n\nWith any luck, she hasn't yet completed its construction, but ye know what happens when we rely on luck...", objectives = "Defeat the Iron Reaver in Hellfire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39250] = { id = 39250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pits of Mannoroth", description = "In the Hellfire Citadel, they're corruptin' a magnaron with fel energy in the Pits o' Mannoroth.\n\nIf ye delve into the fel pools of that place, be on yer guard.", completion = "We can't handle too many more of those fel-corrupted beasts.", objectives = "Defeat Kormrok in Hellfire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39251] = { id = 39251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Court of Blood", description = "A council o' orc clans has assembled and must be taken care of, if ye know what I mean.\n\nGurtogg Bloodboil o' the Bleeding Hollow, Jubei'thos o' the Burning Blade, and Dia Darkwhisper o' the Shadowmoon clan can all be found within the accursed walls of Hellfire Citadel.", objectives = "Defeat the Hellfire High Council in Hellfire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39252] = { id = 39252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deadeye's Vision", description = "Kilrogg Deadeye has led his clan down a dark path that he cannot return from.\n\nDemon blood coursing through his veins, he awaits the moment of his death at yer hands in Hellfire Citadel.", objectives = "Defeat Kilrogg Deadeye in Hellfire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39253] = { id = 39253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maw of Souls", description = "Falling into the heart o' the mausoleum in Auchindoun, Teron'gor gorged upon hundreds o' draenei souls, becoming a bloated abomination in the process. \n\nNo longer recognizable as an orc, Teron'gor gave up his old name and has taken on the mantle of Gorefiend.", progress = "I hope you make Gorefiend pay for his atrocities.", completion = "That was some kind of monster, wasn't it?", objectives = "Defeat Gorefiend in Hellfire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39254] = { id = 39254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iskar's Clutch", description = "I'm afraid I have bad news about someone ye once trusted. The arakkoa Iskar has gone too far in his desire to regain flight, and has joined with Gul'dan to regain his highborn body.\n\nWith it came the price of fel corruption and being doomed to fall at yer hands.", objectives = "Defeat Shadow-Lord Iskar in Hellfire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39255] = { id = 39255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amphitheater of the Eternal", description = "The Exarch betrayer, Socrethar, was defeated with the assistance of Lady Liadrin and Exarch Maladaar.\n\nBut, he has returned. His vile spirit  is now within the Soulbound Construct in Hellfire Citadel, and must be destroyed once again.", objectives = "Defeat the Soulbound Construct in Hellfire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39256] = { id = 39256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temple of Tyranny", description = "Tyrant Velhari was once a promising vindicator, but has turned to Shadow for reasons known only to her.\n\nPurge this Eredar of darkness.", completion = "How does a vindicator fall so far from the light?", objectives = "Defeat Tyrant Velhari in Hellfire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39257] = { id = 39257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grommash's Torment", description = "We believe Grommash has not yet accepted Gul'dan's offer, and may even have avoided drinking the blood offered him.\n\nBut Gul'dan has set Fel Lord Zakuun on Grommash. This demon is Gul'dans best-known torturer.\n\nI fear for Grommash. If he is turned, I fear for us all.", objectives = "Defeat Fel Lord Zakuun in Hellfire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39258] = { id = 39258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Felborne Breach", description = "Summoned by Gul'dan from the depths o' the Twisting Nether, Xhul'horac is one o' the most powerful o' the Void Revenants--a race of parasitic void-beings that tear holes through the planes o' reality, consuming and absorbing the energies and beings within.\n\nGul'dan has twisted Xhul'horac, feeding him overwhelming fel energy, and using his powers to tear open the portals through which he plans to rally the forces o' the Burning Legion.", objectives = "Defeat Xhul'horac in Hellfire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39259] = { id = 39259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destructor's Rise", description = "We believed we were done with Mannoroth, at least for a time. But Gul'dan is more powerful than we thought.\n\nMannoroth is nearly back in this world. His bones have been seen within the citadel, and he must be destroyed before he can reach his full power.", completion = "Let's hope Mannoroth stays down longer this time.", objectives = "Defeat Mannoroth in Hellfire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39260] = { id = 39260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Gate", description = "We've heard rumors that one o' the strongest eredar might enter this world through the Black Gate soon.\n\nIf these rumors are to be believed, it could even be Archimonde the Defiler. If he arrives unchallenged, Draenor itself is likely to fall.", completion = "You have saved Draenor from one of the strongest demons in all creation, Commander. They will sing songs of your victory.", objectives = "Defeat Archimonde in Hellfire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39261] = { id = 39261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of the Illidari", description = "{name}, Kayn requests that you meet him at Krasus' Landing at once.\n\n<Kor'vas leans in close, her voice an urgent whisper.>\n\nYou must hurry. The Legion has eyes everywhere.", completion = "We have much to do, and precious little time to do it.", objectives = "Speak to Kayn Sunfury at Krasus' Landing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39262] = { id = 39262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Give Me Sight Beyond Sight", description = "Jace Darkweaver swears that for a split second he sensed a demonic presence up and behind us. He took some of our forces up to the cave just to the southeast to investigate.\n\nThey found nothing in the cave, but he is certain that something is amiss.\n\nWould you lend him your guidance, and more importantly, your spectral sight?", progress = "{name}, we need you to scan the cave with your spectral sight.\n\nWe must know if there are Legion forces magically hidden within.", completion = "I KNEW that I'd sensed something foul!", objectives = "Speak with Jace Darkweaver and then use your Spectral Sight ability to scan the cave for hidden demons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39263] = { id = 39263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashran Excavation" }
quests[39264] = { id = 39264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bonus Objective: Ashran Excavation" }
quests[39265] = { id = 39265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tiny Viking Helmet" }
quests[39266] = { id = 39266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tiny Plated Helm" }
quests[39267] = { id = 39267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tiny Ninja Shroud" }
quests[39268] = { id = 39268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tiny Pirate Hat" }
quests[39269] = { id = 39269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Never Alone", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39271] = { id = 39271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Mission Sent" }
quests[39272] = { id = 39272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Poisoned Crops", description = "After driving us from the farmland and infesting our crops with insects, the drogbar placed wicked totems that further poison our harvest.\n\nI can only hope that if you destroy them, we'll be able to heal the land using Jale's water magic.\n\nThank you for coming to help us, {name}. We are but simple farmers and fishermen, and have little prowess in combat.", progress = "The crops must be rid of this poison!", completion = "Thank you, {race}. Some of the crops still live. I believe with hard work and some of Jale's magical waters, we will not lose the entire harvest.", objectives = "Destroy the drogbar Poison Idols.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39273] = { id = 39273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Mission Complete" }
quests[39274] = { id = 39274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defend the Riverlands" }
quests[39276] = { id = 39276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strange Tools", description = "We are well on our way to building our first ship, but unfortunately, I am not the orc for the job.  I have no idea how to work with these human tools.  Your shipwright, Yanas Seastrike, is going to take over from here on out.\n\nI will be here at the dry docks if you need anything from me.", completion = "Interested in shipbuilding, I see?  I will do everything I can to help out, commander.", objectives = "Speak with Yanas Seastrike at the dry docks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39277] = { id = 39277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spray and Prey", description = "The Bug Sprayer you recovered from Ormgul the Pestilent seems like it could give us an advantage against the drogbar and their insects.\n\nSpray the Drogbar with their own alchemy and watch their insects turn against them.", progress = "For this group of drogbar to turn against us after so many years of peace...", completion = "That worked quite well. I will hold on to this Bug Sprayer; it might be useful in the battles to come.", objectives = "Use the Bug Sprayer on drogbar in Whitewater Wash.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39278] = { id = 39278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Manifest", description = "The water-proofed manifest contains some form of code for the most part, hiding the contents of the actual manifest. In the corner is a hastily scrawled note for a Mr. Knuckles. \"Shipment attacked, got away but boat is sinking. Get here before they do.\"\n\nThere are coordinates after that which lead to the sunken boat. Mr. Knuckles is definitely the kind of person you want owing you a favor, not the other way around.", progress = "Whatchoo got there?", completion = "Dis... is important! Where you find dis? We been lookin for dis stuff a while.\n\nYou got a dock now? Dat is VERY interesting. Maybe it time we became good friends? Da big fort you have is hard to sneak a spy-- er, forget I said dat.\n\nI gots an idea.", objectives = "Find Mr. Knuckles' missing shipment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39279] = { id = 39279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Mardum" }
quests[39282] = { id = 39282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Second Mission Complete" }
quests[39283] = { id = 39283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felmouth Frenzy Lunker", progress = "You got lunkers, {name}?", completion = "Wow, look at this thing.\n\nI think maybe I'll... actually, I'm not sure what to do with this. Is it really a fish?" }
quests[39285] = { id = 39285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Second Mission Sent" }
quests[39286] = { id = 39286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gruesome Task", description = "So here's the scoop, {name}. One of our agents has found an entrance to the portal world where Sargeras is keeping his personal felhound. We can't strike at him directly, but he's imbued a lot of power into this creature.\n That's the good news.\n\n The bad news, however, is outright gruesome. He's been feeding this monster on the brains of our allies, and that's all it will eat. As horrifying as it is, there's a fresh supply of corpses at the Broken Shore. Head down and get them.", objectives = "Retrieve 5 Severed Heads from the Broken Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39287] = { id = 39287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deathtalon" }
quests[39288] = { id = 39288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terrorfist" }
quests[39289] = { id = 39289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doomroller" }
quests[39290] = { id = 39290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance" }
quests[39292] = { id = 39292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashran Dominance", description = "The Alliance refuse to back down in Ashran. Teach them that the Horde will not stand aside while they plunder the power of the ancient ogre empire to use for their own schemes.", objectives = "Defeat the Alliance at all event locations in Ashran and kill Grand Marshal Tremblade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39294] = { id = 39294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashran Dominance", description = "As we feared the Horde are trying to consolidate their position here on the island by looting it, just like we feared. Get out there and show them the Alliance won't put up with their aggression.", objectives = "Defeat the Horde at all event locations in Ashran and kill High Warlord Volrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39296] = { id = 39296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Fissure Treasure" }
quests[39299] = { id = 39299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Black Marketeering", description = "Ya did us a real solid today, {name}. Boss Goya says you're big stuff in dese parts and we should keep an eye on --- uh, I mean we should be good buds. She's sent a repre... repre... del-e-g... um, a Black Market person to your garrison.\n\nGo say hi and stuff, and make sure to speak loudly when you plan what you're gonna do next.", completion = "I am pleased to make your acquaintance, commander. If you ever wish to see the latest wonders that Madame Goya offers, please do not hesitate to speak with me. She sends this as a token of appreciation for your work in retrieving the manifest.\n\nRemember, Madame Goya only accepts bids in person. You must travel to meet her, if you wish to acquire any of her wares.", objectives = "Speak with Zhang Yeoh in your garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39303] = { id = 39303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Third Mission Sent" }
quests[39304] = { id = 39304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Third Mission Complete" }
quests[39305] = { id = 39305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Empty Nest", description = "I've taken an inventory of the eggs you recovered. Some among the bunch may still have a chance to hatch.\n\nThey will need to be returned to an empty nest, and with any luck, an eagle will claim the eggs as her own and watch over them once again.\n\nThere is a nest just outside the entrance, on a rocky ledge above the cave.\n\nBe careful, {name}. The eggs are very delicate.", progress = "If there's any hope for those eggs hatching, they'll need to be returned to their nest.", completion = "Thanks to you, the great eagles of Highmountain will live on.\n\nOne of the eggs I thought was too damaged to salvage appears to be hatching...", objectives = "Place the eagle eggs in the empty nest above the eastern entrance to Rockcrawler Chasm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39306] = { id = 39306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms" }
quests[39307] = { id = 39307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mechasuit" }
quests[39308] = { id = 39308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bodyguard" }
quests[39309] = { id = 39309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Orb" }
quests[39310] = { id = 39310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artillery Strike" }
quests[39311] = { id = 39311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bitestone Enclave Treasure" }
quests[39312] = { id = 39312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunder Totem Treasure" }
quests[39313] = { id = 39313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring the Reinforcements", description = "Greetings, Commander! With all of the fighting concentrated here in Tanaan, we've got the breathing room to divert some of our resources from nearby outposts to help make headway.\n\nJust let me know which reinforcements to call, and I'll get them here on the double!", progress = "Which allies should I call for?", completion = "Great! I'm always here if ye' ever want to change your mind!", objectives = "Talk to Angar Steelbellow and choose which reinforcements to bring to Tanaan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39315] = { id = 39315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring the Reinforcements", description = "Hey there, Commander. You know, with all of the fighting concentrated here in Tanaan, we've got plenty of extra supplies just sitting around in our nearby outposts.\n\nYou just give me the order and I'll make sure some of them get sent our way!", completion = "A whole slew of artillery options at your hands! Living the dream.\n\nRemember, you can return to me at any time if you change your mind!", objectives = "Talk to Fraggs and choose which reinforcements to bring to Tanaan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39316] = { id = 39316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trapped Tauren", description = "The drogbar just rounded up those of us that they could and led them to a cave near here.\n\nIf you act quickly, I think they can still be saved. I know not what purpose they have for capturing our people.\n\nI shudder to think of it... in the deep places, the darkness rules.", progress = "They slew many of my brothers and sisters, but at least some managed to escape. Others, however, we captured.", completion = "They have returned relatively unharmed. Thank you, {name}.", objectives = "Free the captured Rivermane tauren.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39317] = { id = 39317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siege of Crawliac" }
quests[39318] = { id = 39318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nursing the Wounds", description = "I know why Mayla sent you. But as you have seen, the drogbar are not the only threat to Highmountain.\n\nI will not send forces to support until we deal with the minions of High Crawliac.\n\nIf you want to help, find my shaman. He was supposed to be dispersing these fires that are ravaging my village.\n\nHe was last seen heading for his spirit lodge to the south just before these Cinderwitches descended on us.", progress = "These harpies are all over the place!", completion = "Julan is dead? He was a good shaman and full of life. Not as morbid as some of these spiritwalkers.\n\nI will miss his laughter tonight.", objectives = "Find Windmaster Julan and help extinguish the fires on Skyhorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39321] = { id = 39321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Three", description = "When High Crawliac seized control of the harpies she placed 3 powerful and deadly witches in charge of the covens under her command.\n\nThese witches must die. Feel up for the challenge?\n\nHead into the Haglands behind me and find these three evil creatures.\n\nWe will cover you from the air and give your prey no sky to retreat.\n\nLook for us higher up the mountain, should you survive.", progress = "Many Skyhorn have fallen to the witchcraft of these hags.", completion = "Well done. Now to cut the head off the snake, as it were.", objectives = "Slay Ragi the Hexxer, Agara Deathsong, and Ugla the Hag.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39322] = { id = 39322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Witchqueen", description = "The time has come to assault High Crawliac, the Witchqueen.\n\nYou should know that one does not become queen of the harpies through kindness.\n\nThis creature has killed, betrayed, and tormented countless tauren, harpies, kobolds, and anything else she had to in order to secure her position as queen.\n\nCome, friend, let us finish this.", progress = "Without a queen, it will take the harpies many years before they can organize in such numbers again.", completion = "You have our respect and honor, {name}. I name you Skyfriend, and grant you free passage through our lands at your discretion.", objectives = "Slay High Crawliac, the Witchqueen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39323] = { id = 39323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moozy's Sojourn", description = "My son! They took him! My wife and I split up to look for him. She went upriver and I went downriver.\n\nLeave me, please, and find Moozy... I might be okay... If you find Moozy, please bring him to my wife upriver.", completion = "<Moozy squeals in delight at your presence.>", objectives = "Find Moozy downriver in Whitewater Wash.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39324] = { id = 39324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through the Portal", description = "Here's the good news: you're halfway there. Sorry you had to do that, but necessity is the mother of invention. See that portal down there? That's where the Hound lives. Get through it and find out what's going on in there.", objectives = "Use the Demonic Gateway to enter the Hound's Portal World.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39325] = { id = 39325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Your Mix On", description = "Let's see... potion stains on your tabard, crushed herbs on your boots... I know a fellow alchemist when I see one!\n\nWe will do good work together, the two of us. I trust you're not averse to learning new tricks.\n\nBe sure to use my state-of-the-art alchemy table. I built her myself!", progress = "I hope you're making good use of my alchemy table. It's my pride and joy!", completion = "I trust you were successful in making the potions? This will be the first step in building trust between us.", objectives = "Deucus Valdera in Dalaran wants you to craft some new potions. Merchant Patricia Egan in the alchemy shop can help you learn how.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39326] = { id = 39326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Shipments", description = "Now that we've gotten to know each other, perhaps you can lend me a hand.\n\nMy weekly supply shipment was lost when my longtime courier--you know, old whatsername--was shot out of the sky over the shores of Azsuna. Surely a hardy sort like you could retrieve my lost goods.", progress = "I say, I do hope you were able to locate my lost supplies. How are we to build trust between us if you won't do everything I ask?", completion = "You found them! I had the utmost faith, of course. What's a few demons or naga to one so dedicated to advancing our craft?", objectives = "Alchemist Deucus Valdera in Dalaran wants you to locate supplies lost near the water in Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39327] = { id = 39327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "There's a Scribe for That", description = "Fine! I admit, even my considerable intellect can't translate the strange tome you discovered. No doubt the water smears made it illegible.\n\nSay, one of those dimwitted scribes down the block owes me a favor. This sort of busywork is just his cup of tea.", progress = "I don't have time to translate tomes! That's what lesser professions are for.", completion = "It seems that twerp of a scribe has his uses after all! Let's see what he came up with...", objectives = "Bring the Runewritten Tome to Professor Pallin in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39328] = { id = 39328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Knowledge", description = "The tome contains a wealth of ancient vrykul recipes! Why, I could be the first alchemist in untold ages to craft one! How fortunate for you, friend {name}, that you are here to bear witness to my greatness!\n\nAwful kind of that Svena person to die and leave her book for us, eh? Silly vrykul...", completion = "My poor table!\n\nAll the implements we needed to mix the new potions were on that table. Without them, the new recipes are useless!\n\nFinding replacements will be no small task, but I'm confident you're up to it. If you need guidance, I can suggest places to look for the items we need.\n\nNow, off with you!", objectives = "Observe Deucus Valdera as he attempts one of the vrykul recipes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39329] = { id = 39329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dormant Burner", description = "I've heard that someone over in the engineering shop is selling a burner that might be usable. You could likely negotiate a fairer price than I could!\n\nThe shop is just across the street. I'll make a note on your map for you.", progress = "It's a good thing the other crafters around here make such items. I couldn't imagine wasting my time on such endeavors.", completion = "Ah, this burner is exactly what we need for the alchemy table!\n\nWait just a moment... No, no, this will never do!", objectives = "Purchase a Depleted Leyflame Burner from Hobart Grapplehammer and bring it to Deucus Valdera in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39330] = { id = 39330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ley Hunting", description = "The leyflame burner you brought me is useless! This is why I never trust an engineer...\n\nThe burner needs to be charged in areas that resonate with ley energy before it can be used to craft our newfound alchemy recipes.\n\nLucky for us, Azsuna is rich with such power.", completion = "You imbued the burner with ley energy, eh? Let's have a look.\n\n<Deucus examines the leyflame burner.>\n\nYes, this will do nicely! A crucial step in rebuilding the alchemy table.", objectives = "Travel to key locations in Azsuna and use the Depleted Leyflame Burner to collect ley energy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39331] = { id = 39331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eye of Azshara: Put a Cork in It", description = "A thought occurred to me recently, {name}. The naga have been known to hoard all manner of potions, so they might have the sort of corks we need.\n\nIn my educated opinion, I believe the best place to start searching is around the Eye of Azshara!\n\nTry not to waste your time in there dealing with the naga's goings on, just look for some replacement corks.", progress = "The sooner we get my supplies back, the quicker we can get back to real work.", completion = "What's this? The spoils from another of your adventures, eh? Let's have a look.", objectives = "Go to the Eye of Azshara and retrieve the Advanced Corks for Deucus Valdera in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39332] = { id = 39332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Furbolg Firewater", description = "Oh! I recognize these corks you brought me, {name}. I recently acquired several from a furbolg tribe in Val'sharah. They need sturdy corks to keep a tight seal on that potent firewater they brew.\n\nWe need more firewater potions--the corks would make an ideal addition to our alchemy table!", progress = "Did you find more firewater potions? I bet it's tempting to take a swig!", completion = "These potions have the corks we need for the alchemy table. Another successful endeavor!", objectives = "Acquire skins of Smolderhide Firewater from the furbolg camp in Val'sharah. Bring them back to Deucus Valdera in Dalaran so he can make use of the corks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39333] = { id = 39333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Imprecise Burette", description = "Here are your burettes. Should you ever be in the need of anything else, don't hesitate to ask.\n\n<Ms. Xiulan holds up the hair and continues to chuckle to herself.>", completion = "Oh yes, these are fine. Fine indeed. Unfortunately they need to be calibrated in order to for us to get any accurate readings off of them.", objectives = "Bring the Uncalibrated Malloric Burettes to Deucus in Dalaran.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39334] = { id = 39334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thanks for Flasking", description = "Here is your flask, good as new. A fair trade for those potions.\n\nBe a little more careful with your breakables next time!", completion = "Barm did his work, then? I hoped that tauren would come through!\n\nThis is a very useful addition to my alchemy table.", objectives = "Take the repaired Dual-Chambered Mixing Flask to Deucus Valdera in Dalaran.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39335] = { id = 39335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharion's Lair: Potent Powder", description = "I've heard rumors that the ancient drogbar collected powder from the residue of dragon's breath. If it's true that Neltharion's Lair lies somewhere below us, it seems a likely source.\n\nGo there and try to find a replacement for my powder.", progress = "What have we here?", completion = "You... you found some? I'm impressed, and that doesn't happen easily I'll have you know.\n\nNow let's see what exactly it was that you found...", objectives = "Acquire Precipitating Powder in Neltharion's Lair and bring it to Deucus Valdera in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39336] = { id = 39336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Need More Powder!", description = "The substance you brought me appears to be precipitating powder, a highly volatile reagent used by the vrykul in their recipes.\n\nThere are rumors that a vrykul elder named Katterin has built up quite a store of this powder. A substance this dangerous needs to be in our hands, not hers!", progress = "Let's hope you find the powder we need...", completion = "The ghost of Svena appeared again? Seems she doesn't take kindly to our attempts to learn these vrykul recipes...\n\nThankfully, the satchel you recovered has all the precipitating powder we require for the alchemy table. Another victory for us!", objectives = "Obtain Katterin's Alchemy Kit from Katterin the Blistered in Stormheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39337] = { id = 39337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forlorn Filter", description = "Next on the list of things to replace are my filters. Now I'm sure you've concluded that an alchemist of my caliber uses only the finest of tools when mixing my potions.\n\nThe elves at the Temple of Elune in Val'sharah use Shaldorei silk to craft their robes. Perhaps they'd be willing to part with some for my filters.", progress = "A pile of tattered shaldorei silk lay on the chest.", completion = "This Shaldorei Silk appears to be torn into strips. The elves have apparently been using it as bandages for their fallen warriors.", objectives = "Speak with a Temple Priestess at the Temple of Elune to see if you can acquire some Shaldorei Silk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
